using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Library.Web.Models;using Library.Web.Services;
namespace Library.Web.Pages.Books;
public sealed class IndexModel:PageModel{private readonly LibraryStore _store;public IReadOnlyList<Book> Books{get;private set;}=[];public string? ErrorMessage{get;private set;}[BindProperty]public Book NewBook{get;set;}=new();[BindProperty]public Book EditBook{get;set;}=new();public IndexModel(LibraryStore store)=>_store=store;public void OnGet()=>Load();public IActionResult OnPostCreate(){if(string.IsNullOrWhiteSpace(NewBook.Title)||NewBook.TotalCopies<1){ErrorMessage="Title and at least one copy are required.";Load();return Page();}_store.AddBook(NewBook);return RedirectToPage();}public IActionResult OnPostUpdate(int id){try{var existing=_store.GetBook(id);if(existing is null){ErrorMessage="Book not found.";Load();return Page();}EditBook.BookId=id;EditBook.Isbn ??= existing.Isbn;EditBook.AccessionNumber ??= existing.AccessionNumber;EditBook.BookType ??= existing.BookType;EditBook.Author ??= existing.Author;EditBook.Category ??= existing.Category;EditBook.Title=EditBook.Title.Trim();_store.UpdateBook(EditBook);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}public IActionResult OnPostDelete(int id){try{_store.DeleteBook(id);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}private void Load()=>Books=_store.Books;}
